// Some portions generated by Claude
// Layout benchmark helpers shared by the layout regression tests (ported from the explorer's scripts/).
import { writeFileSync } from 'node:fs';
import { sharedHubNetwork, disconnectedNetwork, chainNetwork } from '../fixtures/layout-networks.mjs';
import { createStarStressGraph } from '../../../../main/frontend/graph-explorer/graph-fixtures.ts';
import { computeGraphLayout } from '../../../../main/frontend/graph-explorer/graph-layout-engine.ts';
import { graphNodeSize, computeEdgePorts, edgeGeometry, edgePortKey, curveSamples } from '../../../../main/frontend/graph-explorer/graph-geometry.ts';
import { measureLayoutConflicts } from '../../../../main/frontend/graph-explorer/graph-layout.ts';

export function layoutMetrics(graph, positions, bends, routes) {
  const index = new Map(graph.nodes.map((n, i) => [n.id, i]));
  const nodes = graph.nodes.map(n => {
    const size = graphNodeSize(n);
    return {entityId: n.id, ...positions.get(n.id), width: size.width + 32, height: size.height + 24, renderWidth: size.width, renderHeight: size.height};
  });
  const links = graph.edges.map(e => [index.get(e.source), index.get(e.target)]);
  const lengths = links.map(([a, b]) => Math.hypot(nodes[a].x - nodes[b].x, nodes[a].y - nodes[b].y)).sort((a, b) => a - b);
  const width = Math.max(...nodes.map(n => n.x + n.renderWidth / 2)) - Math.min(...nodes.map(n => n.x - n.renderWidth / 2));
  const height = Math.max(...nodes.map(n => n.y + n.renderHeight / 2)) - Math.min(...nodes.map(n => n.y - n.renderHeight / 2));
  let routedEdgeNodeOverlaps;
  if (bends) {
    routedEdgeNodeOverlaps = 0;
    const placed = graph.nodes.map(n => ({...n, ...positions.get(n.id)}));
    const byId = new Map(placed.map(n => [n.id, n])), ports = computeEdgePorts(placed, graph.edges);
    for (const edge of graph.edges) {
      const curve = edgeGeometry(byId.get(edge.source), byId.get(edge.target), bends.get(edge.id) ?? 0, ports.get(edgePortKey(edge.id, edge.source)), ports.get(edgePortKey(edge.id, edge.target)), routes?.get(edge.id));
      // A stepped route is tested leg by leg: chords between samples of it would cut the corners it goes round.
      const samples = curve.points ?? curveSamples(curve, 12);
      for (const box of nodes) {
        if (box.entityId === edge.source || box.entityId === edge.target) continue;
        if (samples.some((a, i) => i && segmentBox(samples[i - 1], a, box))) routedEdgeNodeOverlaps++;
      }
    }
  }
  return {...measureLayoutConflicts(nodes, links), ...(routedEdgeNodeOverlaps === undefined ? {} : {routedEdgeNodeOverlaps}), width, height, area: width * height, medianEdge: lengths[Math.floor(lengths.length / 2)], p95Edge: lengths[Math.floor(lengths.length * .95)], maxEdge: lengths.at(-1)};
}

function segmentBox(a, b, box) {
  let lo = 0, hi = 1;
  for (const [axis, size] of [['x', 'renderWidth'], ['y', 'renderHeight']]) {
    const delta = b[axis] - a[axis], lower = box[axis] - box[size] / 2, upper = box[axis] + box[size] / 2;
    if (Math.abs(delta) < 1e-9) {if (a[axis] < lower || a[axis] > upper) return false;}
    else {const t0 = (lower - a[axis]) / delta, t1 = (upper - a[axis]) / delta; lo = Math.max(lo, Math.min(t0, t1)); hi = Math.min(hi, Math.max(t0, t1));}
    if (hi < lo) return false;
  }
  return true;
}

if (process.argv[1]?.endsWith('benchmark-layout.mjs')) {
  const results = [];
  for (const [name, graph] of [['shared-hubs-237', sharedHubNetwork()], ['components-96', disconnectedNetwork()], ['chain-80', chainNetwork()], ['star-300', createStarStressGraph(300, 1)]]) {
    const started = performance.now();
    const result = await computeGraphLayout(graph);
    const ms = performance.now() - started;
    const row = {name, nodes: graph.nodes.length, edges: graph.edges.length, ms, ...layoutMetrics(graph, result.positions, result.bends)};
    results.push(row);
    console.log(JSON.stringify(row));
  }
  const output = process.argv.indexOf('--json');
  if (output >= 0) writeFileSync(process.argv[output + 1], JSON.stringify({node: process.version, results}, null, 2) + '\n');
}
